// Biometric speed index — record JAH-GPC-FINGERPRINTREADER-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"match_ms": 800, "templates": 10};
var value = (1000/m.match_ms*m.templates);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-FINGERPRINTREADER-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-FINGERPRINTREADER-000001|' + value.toFixed(2) + ' speed index');

